import { test } from 'node:test'
import assert from 'node:assert/strict'
import { renderToolsSdk } from '@deepseek-ai/dsh-tools'
import { adaptCliSystemPrompt } from '../src/provider/cli-tool-instructions.ts'
import { buildPromptPlan, type PromptPlanInput } from '../src/provider/prompt.ts'
import { resolveCallContext } from '../src/provider/call-context.ts'
import { purposePolicy } from '../src/provider/purpose-policy.ts'
import { defaultConfig } from '../src/common/types.ts'
import type { AgyGenerateOptions } from '../src/common/protocol.ts'

// Neutral fixtures generated by the real DSH renderer: no local prompts or data.
const exclusive = '`run_code` is the only tool you can call directly — a tool call naming any other tool fails. Reach every tool the SDK declares below from inside the program.'
const prefix = 'Role: technical assistant.\nPermission: ask before writes.\n'
const tail = '\n\n## Remaining constraints\nRetain approval rules.\nTask: explain the quoted words run_code and tools.inspect.\n'
const schemas: Parameters<typeof renderToolsSdk>[0] = [
  { name: 'inspect', description: 'Inspect a synthetic record', parameters: { type: 'object', properties: {} }, output: { type: 'string' } },
  { name: 'bash', description: 'Synthetic shell binding', parameters: { type: 'object', properties: { command: { type: 'string' } }, required: ['command'] }, output: { type: 'string' } },
]
const sdk = renderToolsSdk(schemas)
const system = prefix + exclusive + '\n\n' + sdk + tail

function assertAdapted(value: string, expectedTail = tail) {
  assert.ok(value.startsWith(prefix))
  assert.ok(value.endsWith(expectedTail))
  assert.ok(!value.includes(exclusive))
  assert.ok(!value.includes('## Writing code for run_code'))
  assert.ok(!value.includes('Program-only SDK bindings:'))
  assert.ok(!value.includes('declare const tools:'))
  assert.ok(value.includes('MCP dev_tool_search'))
  assert.ok(value.includes('toolNames'))
  assert.ok(value.includes('refresh tools/list'))
  assert.ok(value.includes('notifications/tools/list_changed'))
  assert.ok(value.includes('refreshed schema'))
  assert.ok(value.includes('all task, permission and safety instructions remain in force'))
}

test('recognises real native TypeScript renderer output including its bash invocation example', () => {
  assert.ok(sdk.startsWith('## Writing code for run_code\n\n'))
  assert.ok(sdk.includes('Program-only SDK bindings:\n\n```ts\n'))
  assert.ok(sdk.includes('run_code({ code:'))
  assertAdapted(adaptCliSystemPrompt(system))
})

test('recognises the comma-separated code argument emitted by newer DSH renderers', () => {
  const current = sdk.replace('arguments: `code` — ', 'arguments: `code`, ').replace(' — and `description`', ', and `description`')
  assertAdapted(adaptCliSystemPrompt(prefix + exclusive + '\n\n' + current + tail))
})

test('recognises an empty complete renderer SDK without broadening the match', () => {
  assertAdapted(adaptCliSystemPrompt(prefix + exclusive + '\n\n' + renderToolsSdk([]) + tail))
})

test('preserves every byte of the prefix, task and SDK tail and is idempotent', () => {
  const value = adaptCliSystemPrompt(system)
  assertAdapted(value)
  assert.equal(adaptCliSystemPrompt(value), value)
  assert.ok(value.includes('quoted words run_code and tools.inspect'))
})

test('preserves CRLF prompt content and trailing text', () => {
  const crlf = system.replaceAll('\n', '\r\n')
  const value = adaptCliSystemPrompt(crlf)
  assert.ok(value.startsWith(prefix.replaceAll('\n', '\r\n')))
  assert.ok(value.endsWith(tail.replaceAll('\n', '\r\n')))
  assert.ok(!value.includes(exclusive))
  assert.equal(adaptCliSystemPrompt(value), value)
})

test('preserves mixed newlines and a verbatim native instruction quoted after the SDK', () => {
  const mixedTail = tail.replace('Retain approval rules.\n', 'Retain approval rules.\r\n') + exclusive + '\r\n'
  const input = prefix.replaceAll('\n', '\r\n') + exclusive + '\r\n\r\n' + sdk + mixedTail
  const result = adaptCliSystemPrompt(input)
  assert.ok(result.startsWith(prefix.replaceAll('\n', '\r\n')))
  assert.ok(result.endsWith(mixedTail))
  assert.equal(adaptCliSystemPrompt(result), result)
})

test('leaves non-PTC prompts, ordinary quotes and standalone mentions byte-identical', () => {
  for (const input of ['', prefix + tail, 'Quoted: ' + exclusive, exclusive, sdk, system.replace(exclusive, 'Quoted: ' + exclusive), system.replaceAll('\n', '\n> ')]) {
    assert.equal(adaptCliSystemPrompt(input), input)
  }
})

test('does not rewrite SDK examples enclosed in an outer code fence', () => {
  for (const fence of ['````text', '~~~text']) {
    const quoted = fence + '\n' + system + '\n' + fence.replace('text', '')
    assert.equal(adaptCliSystemPrompt(quoted), quoted)
  }
})

test('leaves incomplete or changed native SDK boundaries byte-identical', () => {
  for (const input of [
    system.replace('## Writing code for run_code', '## Similar section'),
    system.replace('Inside the program:', 'Changed program:'),
    system.replace('Program-only SDK bindings:', 'Changed bindings:'),
    system.replace('interface ToolArgsMap {', 'interface MissingArgs {'),
    system.replace('interface ToolOutputMap {', 'interface MissingOutput {'),
    system.replace('type ToolName = keyof ToolOutputMap', 'type ToolName = string'),
    system.replace('declare class ToolCallError extends Error {', 'declare class MissingError {'),
    system.replace('declare const tools: {', 'declare const missing: {'),
    system.replace('\n```' + tail, '\n```extra' + tail),
    system.slice(0, system.lastIndexOf('\n```')),
  ]) assert.equal(adaptCliSystemPrompt(input), input)
})

async function promptPlan({ primary = system, fallback, forward = true, purpose = 'chat' }: {
  primary?: string; fallback?: string; forward?: boolean; purpose?: 'chat' | 'session-title'
} = {}) {
  const options = {
    provider: 'antigravity', model: 'test-model', purpose,
    system: primary,
    messages: [...(fallback ? [{ role: 'system', content: [{ type: 'text', text: fallback }] }] : []),
      { role: 'user', content: [{ type: 'text', text: 'Explain this synthetic task.' }] }],
  } as AgyGenerateOptions
  const cfg = { ...defaultConfig(), forwardSystemPrompt: forward, contextTransfer: 'off' as const }
  const ctx = resolveCallContext({ options, cfg, bin: 'synthetic-cli', warnOnce() {}, cwd: '' })
  return buildPromptPlan({
    options, cfg, ctx, policy: purposePolicy(ctx), account: undefined, model: 'test-model', activeModel: 'test-model',
    deps: { store: {} as PromptPlanInput['deps']['store'], getActiveRun: () => undefined,
      recentlyCompactedSessions: new Map(), deliverContext: async (digest) => digest },
  })
}

test('real prompt assembly adapts options.system at the forwarding boundary', async () => {
  const plan = await promptPlan()
  assert.ok(plan.prompt.startsWith('System instructions:\n' + adaptCliSystemPrompt(system)))
  assert.ok(plan.prompt.includes('Explain this synthetic task.'))
  assert.ok(!plan.prompt.includes(exclusive))
})

test('real prompt assembly also adapts the fallback system message', async () => {
  const plan = await promptPlan({ primary: '', fallback: system })
  assert.ok(plan.prompt.startsWith('System instructions:\n' + adaptCliSystemPrompt(system.trim())))
  assert.ok(!plan.prompt.includes(exclusive))
})

test('forwarding opt-out and non-PTC system instructions keep existing behaviour', async () => {
  const omitted = await promptPlan({ forward: false })
  assert.ok(!omitted.prompt.includes('System instructions:'))
  assert.ok(!omitted.prompt.includes(exclusive))
  const plain = prefix + 'Return a concise technical answer.'
  const forwarded = await promptPlan({ primary: plain })
  assert.ok(forwarded.prompt.startsWith('System instructions:\n' + plain + '\n\n'))
})

test('title forwarding adapts PTC while retaining its output protocol', async () => {
  const titleSystem = system + '\nOutput protocol: return a short title.'
  const plan = await promptPlan({ primary: titleSystem, purpose: 'session-title', forward: false })
  assert.ok(plan.prompt.startsWith('System instructions:\n' + adaptCliSystemPrompt(titleSystem)))
  assert.ok(plan.prompt.includes('Output protocol: return a short title.'))
  assert.ok(!plan.prompt.includes(exclusive))
})
